CREATE COLUMN TABLE "TEST_AP"."AIN8" ("DocEntry" INTEGER CS_INT NOT NULL , "CounterNum" INTEGER CS_INT NOT NULL , "CounteType" INTEGER CS_INT DEFAULT 12 NOT NULL , "CounterId" INTEGER CS_INT NOT NULL , "CounteName" NVARCHAR(155), "LogIns" INTEGER CS_INT NOT NULL , "VisOrder" INTEGER CS_INT, PRIMARY KEY ("DocEntry", "CounterNum", "LogIns")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "AIN8_BUSINESS" ON "TEST_AP"."AIN8" ( "DocEntry" ASC, "CounteType" ASC, "CounterId" ASC, "LogIns" ASC )